    /**
     * The badge as a glTF binary, textures and all, its metal plated in
     * `metal`, `scale` badge-widths across. Blocks: call it off the main
     * thread.
     */
    fun `glb`(`scale`: kotlin.Float, `metal`: Rgba): kotlin.ByteArray
    
    fun `materials`(): List<Material>
    
    fun `submeshes`(): List<Submesh>
    
    /**
     * What the materials' textures are made of, in the order they index.
     */
    fun `textures`(): List<Texture>
    
    companion object
}

/**
 * A minted badge. Immutable; buffers are copied out on request.
 */
internal open class LusterBadge: Disposable, AutoCloseable, LusterBadgeInterface
{

    @Suppress("UNUSED_PARAMETER")
    /**
     * @suppress
     */
    constructor(withHandle: UniffiWithHandle, handle: Long) {
        this.handle = handle
        this.cleanable = UniffiLib.CLEANER.register(this, UniffiCleanAction(handle))
    }

    /**
     * @suppress
     *
     * This constructor can be used to instantiate a fake object. Only used for tests. Any
     * attempt to actually use an object constructed this way will fail as there is no
     * connected Rust object.
     */
    @Suppress("UNUSED_PARAMETER")
    constructor(noHandle: NoHandle) {
        this.handle = 0
        this.cleanable = null
    }

    protected val handle: Long
    protected val cleanable: UniffiCleaner.Cleanable?

    private val wasDestroyed = AtomicBoolean(false)
    private val callCounter = AtomicLong(1)

    /**
     * Whether the current object has been destroyed and its reference is gone in the Rust side.
     */
    val uniffiIsDestroyed: Boolean get() = wasDestroyed.get()

    override fun destroy() {
        // Only allow a single call to this method.
        // TODO: maybe we should log a warning if called more than once?
        if (this.wasDestroyed.compareAndSet(false, true)) {
            // This decrement always matches the initial count of 1 given at creation time.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable?.clean()
            }
        }
    }

    @Synchronized
    override fun close() {
        this.destroy()
    }

    internal inline fun <R> callWithHandle(block: (handle: Long) -> R): R {
        // Check and increment the call counter, to keep the object alive.
        // This needs a compare-and-set retry loop in case of concurrent updates.
        do {
            val c = this.callCounter.get()
            if (c == 0L) {
                throw IllegalStateException("${this.javaClass.simpleName} object has already been destroyed")
            }
            if (c == Long.MAX_VALUE) {
                throw IllegalStateException("${this.javaClass.simpleName} call counter would overflow")
            }
        } while (! this.callCounter.compareAndSet(c, c + 1L))
        // Now we can safely do the method call without the handle being freed concurrently.
        try {
            return block(this.uniffiCloneHandle())
        } finally {
            // This decrement always matches the increment we performed above.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable?.clean()
            }
        }
    }

    // Use a static inner class instead of a closure so as not to accidentally
    // capture `this` as part of the cleanable's action.
    private class UniffiCleanAction(private val handle: Long) : Runnable {
        override fun run() {
            if (handle == 0.toLong()) {
                // Fake object created with `NoHandle`, don't try to free.
                return;
            }
            uniffiRustCall { status ->
                UniffiLib.uniffi_luster_ffi_fn_free_lusterbadge(handle, status)
            }
        }
    }

    /**
     * @suppress
     */
    fun uniffiCloneHandle(): Long {
        if (handle == 0.toLong()) {
            throw InternalException("uniffiCloneHandle() called on NoHandle object");
        }
        return uniffiRustCall() { status ->
            UniffiLib.uniffi_luster_ffi_fn_clone_lusterbadge(handle, status)
        }
    }

    override fun `designKey`(): kotlin.String {
            return FfiConverterString.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_luster_ffi_fn_method_lusterbadge_design_key(
        it,
        _status)
}
    }
    )
    }
    

    
    /**
     * The badge as a glTF binary, textures and all, its metal plated in
     * `metal`, `scale` badge-widths across. Blocks: call it off the main
     * thread.
     */override fun `glb`(`scale`: kotlin.Float, `metal`: Rgba): kotlin.ByteArray {
            return FfiConverterByteArray.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_luster_ffi_fn_method_lusterbadge_glb(
        it,
        
        FfiConverterFloat.lower(`scale`),
        FfiConverterTypeRgba.lower(`metal`),_status)
}
    }
    )
    }
    

    override fun `materials`(): List<Material> {
            return FfiConverterSequenceTypeMaterial.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_luster_ffi_fn_method_lusterbadge_materials(
        it,
        _status)
}
    }
    )
    }
    

    override fun `submeshes`(): List<Submesh> {
            return FfiConverterSequenceTypeSubmesh.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_luster_ffi_fn_method_lusterbadge_submeshes(
        it,
        _status)
}
    }
    )
    }
    

    
    /**
     * What the materials' textures are made of, in the order they index.
     */override fun `textures`(): List<Texture> {
            return FfiConverterSequenceTypeTexture.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_luster_ffi_fn_method_lusterbadge_textures(
        it,
        _status)
}
    }
    )
    }
    

    

    


    
    
    /**
     * @suppress
     */
    companion object
    
}


/**
 * @suppress
 */
internal object FfiConverterTypeLusterBadge: FfiConverter<LusterBadge, Long> {
    override fun lower(value: LusterBadge): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): LusterBadge {
        return LusterBadge(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): LusterBadge {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: LusterBadge) = 8UL

    override fun write(value: LusterBadge, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}


