    uniffiRustCall() { _status ->
    UniffiLib.uniffi_luster_ffi_fn_constructor_mintrequest_new(
    
        
        FfiConverterByteArray.lower(`svg`),
        FfiConverterTypeMintOptions.lower(`options`),_status)
}
    )

    protected val handle: Long
    protected val cleanable: UniffiCleaner.Cleanable?

    private val wasDestroyed = AtomicBoolean(false)
    private val callCounter = AtomicLong(1)

    /**
     * Whether the current object has been destroyed and its reference is gone in the Rust side.
     */
    val uniffiIsDestroyed: Boolean get() = wasDestroyed.get()

    override fun destroy() {
        // Only allow a single call to this method.
        // TODO: maybe we should log a warning if called more than once?
        if (this.wasDestroyed.compareAndSet(false, true)) {
            // This decrement always matches the initial count of 1 given at creation time.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable?.clean()
            }
        }
    }

    @Synchronized
    override fun close() {
        this.destroy()
    }

    internal inline fun <R> callWithHandle(block: (handle: Long) -> R): R {
        // Check and increment the call counter, to keep the object alive.
        // This needs a compare-and-set retry loop in case of concurrent updates.
        do {
            val c = this.callCounter.get()
            if (c == 0L) {
                throw IllegalStateException("${this.javaClass.simpleName} object has already been destroyed")
            }
            if (c == Long.MAX_VALUE) {
                throw IllegalStateException("${this.javaClass.simpleName} call counter would overflow")
            }
        } while (! this.callCounter.compareAndSet(c, c + 1L))
        // Now we can safely do the method call without the handle being freed concurrently.
        try {
            return block(this.uniffiCloneHandle())
        } finally {
            // This decrement always matches the increment we performed above.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable?.clean()
            }
        }
    }

    // Use a static inner class instead of a closure so as not to accidentally
    // capture `this` as part of the cleanable's action.
    private class UniffiCleanAction(private val handle: Long) : Runnable {
        override fun run() {
            if (handle == 0.toLong()) {
                // Fake object created with `NoHandle`, don't try to free.
                return;
            }
            uniffiRustCall { status ->
                UniffiLib.uniffi_luster_ffi_fn_free_mintrequest(handle, status)
            }
        }
    }

    /**
     * @suppress
     */
    fun uniffiCloneHandle(): Long {
        if (handle == 0.toLong()) {
            throw InternalException("uniffiCloneHandle() called on NoHandle object");
        }
        return uniffiRustCall() { status ->
            UniffiLib.uniffi_luster_ffi_fn_clone_mintrequest(handle, status)
        }
    }

    
    /**
     * The badge, once it is struck; `Cancelled` once given up.
     */
    @Throws(LusterException::class)
    @Suppress("ASSIGNED_BUT_NEVER_ACCESSED_VARIABLE")
    override suspend fun `badge`() : LusterBadge {
        return uniffiRustCallAsync(
        callWithHandle { uniffiHandle ->
            UniffiLib.uniffi_luster_ffi_fn_method_mintrequest_badge(
                uniffiHandle,
                
            )
        },
        { future, callback, continuation -> UniffiLib.ffi_luster_ffi_rust_future_poll_u64(future, callback, continuation) },
        { future, continuation -> UniffiLib.ffi_luster_ffi_rust_future_complete_u64(future, continuation) },
        { future -> UniffiLib.ffi_luster_ffi_rust_future_free_u64(future) },
        // lift function
        { FfiConverterTypeLusterBadge.lift(it) },
        // Error FFI converter
        LusterException.ErrorHandler,
    )
    }

    
    /**
     * Gives the badge up: `badge` ends with `Cancelled`, and the engine stops
     * if nobody else wants it. Nothing once it has come.
     */override fun `cancel`()
        = 
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_luster_ffi_fn_method_mintrequest_cancel(
        it,
        _status)
}
    }
    
    

    

    


    
    
    /**
     * @suppress
     */
    companion object
    
}


/**
 * @suppress
 */
internal object FfiConverterTypeMintRequest: FfiConverter<MintRequest, Long> {
    override fun lower(value: MintRequest): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): MintRequest {
        return MintRequest(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): MintRequest {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: MintRequest) = 8UL

    override fun write(value: MintRequest, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



