internal sealed class LusterException: kotlin.Exception() {
    
    class InvalidSvg(
        
        val `reason`: kotlin.String
        ) : LusterException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class InputTooComplex(
        
        val `reason`: kotlin.String
        ) : LusterException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class NothingToMint(
        ) : LusterException() {
        override val message
            get() = ""
    }
    
    class Cancelled(
        ) : LusterException() {
        override val message
            get() = ""
    }
    
    class Internal(
        
        val `reason`: kotlin.String
        ) : LusterException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<LusterException> {
        override fun lift(error_buf: RustBuffer.ByValue): LusterException = FfiConverterTypeLusterError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
internal object FfiConverterTypeLusterError : FfiConverterRustBuffer<LusterException> {
    override fun read(buf: ByteBuffer): LusterException {
        

        return when(buf.getInt()) {
            1 -> LusterException.InvalidSvg(
                FfiConverterString.read(buf),
                )
            2 -> LusterException.InputTooComplex(
                FfiConverterString.read(buf),
                )
            3 -> LusterException.NothingToMint()
            4 -> LusterException.Cancelled()
            5 -> LusterException.Internal(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: LusterException): ULong {
        return when(value) {
            is LusterException.InvalidSvg -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is LusterException.InputTooComplex -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is LusterException.NothingToMint -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is LusterException.Cancelled -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is LusterException.Internal -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
    }

    override fun write(value: LusterException, buf: ByteBuffer) {
        when(value) {
            is LusterException.InvalidSvg -> {
                buf.putInt(1)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is LusterException.InputTooComplex -> {
                buf.putInt(2)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is LusterException.NothingToMint -> {
                buf.putInt(3)
                Unit
            }
            is LusterException.Cancelled -> {
                buf.putInt(4)
                Unit
            }
            is LusterException.Internal -> {
                buf.putInt(5)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




