/**
 * @suppress
 */
internal object FfiConverterOptionalUInt: FfiConverterRustBuffer<kotlin.UInt?> {
    override fun read(buf: ByteBuffer): kotlin.UInt? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterUInt.read(buf)
    }

    override fun allocationSize(value: kotlin.UInt?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterUInt.allocationSize(value)
        }
    }

    override fun write(value: kotlin.UInt?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterUInt.write(value, buf)
        }
    }
}




/**
 * @suppress
 */
internal object FfiConverterSequenceTypeLight: FfiConverterRustBuffer<List<Light>> {
    override fun read(buf: ByteBuffer): List<Light> {
        val len = buf.getInt()
        return List<Light>(len) {
            FfiConverterTypeLight.read(buf)
        }
    }

    override fun allocationSize(value: List<Light>): ULong {
        val sizeForLength = 4UL
        val sizeForItems = value.map { FfiConverterTypeLight.allocationSize(it) }.sum()
        return sizeForLength + sizeForItems
    }

    override fun write(value: List<Light>, buf: ByteBuffer) {
        buf.putInt(value.size)
        value.iterator().forEach {
            FfiConverterTypeLight.write(it, buf)
        }
    }
}




